 arch/powerpc/kernel/eeh.c                    | 16 ++++++++++++
 arch/powerpc/kernel/rtas_pci.c               | 26 ++++++++++++++++++++
 arch/powerpc/platforms/pseries/eeh_pseries.c | 16 ++++++++++++
 4 files changed, 67 insertions(+)

